class Solution {
public:
    int arithmeticTriplets(vector<int>& nums, int diff) {
        set<int> seen;
        int count = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (seen.count(nums[i] - diff) && seen.count(nums[i] - 2 * diff)) count++;
            seen.insert(nums[i]);
        }
        return count;
    }
};
